package com.dormrepair.order.controller;
import com.dormrepair.common.result.*; import com.dormrepair.order.dto.*; import com.dormrepair.order.service.*; import com.dormrepair.order.vo.*;
import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/student/repair-orders") @PreAuthorize("hasRole('STUDENT')")
public class StudentRepairOrderController { private final RepairOrderQueryService queries; private final RepairOrderDetailService details; private final StudentRepairOrderCreationService creation; public StudentRepairOrderController(RepairOrderQueryService q,RepairOrderDetailService d,StudentRepairOrderCreationService c){queries=q;details=d;creation=c;} @GetMapping public Result<PageResult<RepairOrderListItem>> page(@ModelAttribute RepairOrderQueryRequest q){q.setWorkerId(null);return Result.success(queries.page(q));} @GetMapping("/{id}") public Result<RepairOrderDetailResponse> detail(@PathVariable Long id){return Result.success(details.getDetail(id));} @PostMapping("/check-duplicate") public Result<RepairOrderDuplicateCheckResponse> checkDuplicate(@Valid @RequestBody RepairOrderDuplicateCheckRequest r){return Result.success(creation.checkDuplicate(r));} @PostMapping public Result<CreateRepairOrderResponse> create(@Valid @RequestBody CreateRepairOrderRequest r){return Result.success(creation.create(r));} }
